import{_ as r,l as o,o as e,c as s,v as l,p as i,x as n,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"向量处理器与 lane","description":"","frontmatter":{"title":"向量处理器与 lane","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vector-lanes.md","filePath":"cs/vector-lanes.md","lastUpdated":1789023840000}'),h={name:"cs/vector-lanes.md"};function m(A,a,_,f,u,D){const t=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="向量处理器与-lane" tabindex="-1">向量处理器与 lane <a class="header-anchor" href="#向量处理器与-lane" aria-label="Permalink to &quot;向量处理器与 lane&quot;">​</a></h1><div class="epigraph"><p>一条向量指令对寄存器里的一列元素流水；lane 是并行的 ALU 切片，元素间没有指令级的译码，只有数据通路的重复。</p><footer>—— 据 Russell, The CRAY-1 Computer System；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/dataflow-dae">上一课</a> 用队列藏延迟。<a href="/cs/flynn-taxonomy">Flynn</a> 的 SIMD 格还没有硬件形状。ISA 对照已有 <a href="/cs/rvv-vector">RVV</a> 与 <a href="/cs/simd-extensions">SIMD 扩展</a>。本课不重讲 token。缺口是<strong>向量机：向量寄存器、条带挖掘、lane，以及它与乱序标量核的分工。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>科学循环里相邻迭代几乎无控制相关。超标量仍要为每条 <code>add</code> 付取指与重命名。<a href="/cs/vliw-epic">VLIW</a> 要把它们打进束。向量：编译器或程序员发一条 <code>vadd</code>，硬件在 lane 上对 <code>vl</code> 个元素流水。缺口不是 MIMD 核数，而是<strong>把循环的内层变成数据通路宽度。</strong></p><p><span class="marginnote">Cray-1：向量寄存器、链式、内存条带。当代 CPU 的 AVX 是短向量；RVV 把 <code>vl</code> 做成架构状态。GPU 的 SIMT 下一课用 warp 包装类似的 lane。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>向量寄存器文件切成 lane：lane \\(i\\) 处理元素 \\(i, i+L, \\ldots\\)。访存单元按步长从内存条带取，对齐则满带宽，散乱则退化。掩码处理条件循环，避免把 SIMD 拆成标量。链式：前一条的结果元素直接进下一条，不必等整向量写回。</p>',8)),(e(),i(p,null,{default:n(()=>[c(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20VADD%5B%22%E4%B8%80%E6%9D%A1%20vadd%22%5D%20--%3E%20L0%5B%22lane%200%22%5D%0A%20%20VADD%20--%3E%20L1%5B%22lane%201%22%5D%0A%20%20VADD%20--%3E%20LN%5B%22lane%20L-1%22%5D%0A%20%20MEM%5B%22%E6%9D%A1%E5%B8%A6%E8%AE%BF%E5%AD%98%22%5D%20--%3E%20L0%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/cpi-amdahl">阿姆达尔</a> 的 \\(f\\) 是不可向量化段（以及 gather 失败）。向量长度覆盖延迟：足够长则流水充满，MLP 来自多个未完成的向量内存包。与乱序标量：标量核跑控制与余数，向量单元跑内核。不要在这里写张量核训练循环——那是 DSA 与大模型栏的边界，本课只到通用向量。</p><p>条带冲突：多个 lane 同时打同一 DRAM bank 会把向量访存串行化，表面上「已向量化」仍落在带宽墙内侧。这与 GPU <a href="/cs/memory-coalescing">合并</a> 是同一几何，只是粒度是向量寄存器而不是 warp。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 GPU warp 调度写完，下一课 SIMT。也不把脉动阵列的空间流水当成向量寄存器。RVV 的具体编码已在 ISA 课，这里只留微结构：lane 与内存条带。</p><p>后课默认：规则数据并行优先用向量/SIMD 通路。把 lane 绑到大量线程、用掩码处理分支，是 GPU SIMT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>向量指令在 lane 上流水，取指开销按整条向量摊。</li><li>条带与对齐决定内存带宽；掩码处理条件。</li><li>GPU 用 warp 共享 PC 驱动类似 lane，下一课。</li><li>出处：Russell, Cray-1；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const T=r(h,[["render",m]]);export{S as __pageData,T as default};
